/// The Maki pictograms (CC0) compiled into fvkit as one SDF sprite sheet,
/// named by their Maki names (`restaurant`, `circle`, `star-stroked`).
/// Generated by port/tools/make_maki_sheet.py.

#ifndef FVKIT_SYMBOL_BUILTIN_ICONS_H_
#define FVKIT_SYMBOL_BUILTIN_ICONS_H_

#include <memory>

#include "fvkit/symbol/png_library.h"

namespace fv {

/// The shared builtin icon sheet, decoded on first use. Every tile is
/// decoded up front, so the library is read-only afterwards and safe to share
/// across threads.
std::shared_ptr<PngSymbolLibrary> BuiltinIconSheet();

}  // namespace fv

#endif  // FVKIT_SYMBOL_BUILTIN_ICONS_H_
